export type Role = "owner" | "admin" | "operator" | "viewer";
export type Action = "start" | "stop" | "restart" | "delete" | "refresh-login-qr" | "read-container-logs" | "update-onebot-websockets";
export interface Envelope { algorithm: "aes-256-gcm"; iv: string; tag: string; ciphertext: string }
export interface Principal { userId: string; email: string; workspaceId: string; role: Role; sessionId: string; csrfHash: string }
export interface Endpoint { id: string; workspaceId: string; name: string; providerId: string; node: { id: string; name: string } | null; generation: number; desired: { state: "running" | "stopped" }; status: { node: string; runtime: string; provider: string; protocol: string; convergence: string }; activeOperationId: string | null; activeOperation: {id:string;action:Action;status:"queued"|"running";progress:OperationProgress;createdAt:string;updatedAt:string}|null; configuration?: Record<string, unknown>; metadata?: Record<string, unknown> }
export type OperationProgressPhase = "queued"|"dispatching"|"agent-acknowledged"|"inspecting-runtime"|"preparing-runtime"|"creating-container"|"starting-container"|"stopping-container"|"removing-runtime"|"applying-configuration"|"retrying"|"probing-provider"|"completed"|"failed";
export interface OperationProgress { phase: OperationProgressPhase; percent: number; message: string; sequence: number; updatedAt: string }
export interface Operation { id: string; workspaceId: string; endpointId: string; generation: number; action: Action; idempotencyKey: string; status: "queued"|"running"|"succeeded"|"failed"|"stale"; attempts: number; result: unknown; progress: OperationProgress; createdAt: string; updatedAt: string; claimedAt: string | null }
export interface NodeCredential { nodeId: string; workspaceId: string; nodeSecret: string }
export interface AuthenticatedNode { id: string; workspaceId: string; name: string; connectionEpoch: number }
export interface AgentCommand { commandId: string; operationId: string; workspaceId: string; nodeId: string; endpointId: string; generation: number; connectionEpoch: number; attempt: number; action: Action; runtimeRequest: unknown; metadata: Record<string, unknown> }
export type AlertEventType="endpoint.offline"|"endpoint.recovery";
export type QqLoginAlertState="unknown"|"online"|"offline";
export function evaluateQqLoginAlertTransition(input:{incidentOpen:boolean;observedAt:Date|null;qqOnline:boolean|null;now:Date;graceSeconds:number}):{state:QqLoginAlertState;incidentOpen:boolean;event:AlertEventType|null}{
  const fresh=input.observedAt!==null&&input.now.getTime()-input.observedAt.getTime()<=input.graceSeconds*1000&&input.observedAt.getTime()<=input.now.getTime();
  if(!fresh||input.qqOnline===null)return{state:"unknown",incidentOpen:input.incidentOpen,event:null};
  if(!input.qqOnline)return{state:"offline",incidentOpen:true,event:input.incidentOpen?null:"endpoint.offline"};
  return{state:"online",incidentOpen:false,event:input.incidentOpen?"endpoint.recovery":null};
}
export interface AlertSubscriptionInput {endpointId:string;offlineTargetIds:string[];recoveryTargetIds:string[]}
export class DatabaseError extends Error { constructor(public code: "not_found"|"conflict"|"idempotency_mismatch"|"already_bootstrapped"|"unauthorized"|"forbidden", message:string=code){super(message)} }
export const digest = (value:string) => createHash("sha256").update(value).digest("hex");
export function encryptSecret(value:string,key:Buffer):Envelope { if(key.length!==32) throw new Error("master key must be 32 bytes"); const iv=randomBytes(12), c=createCipheriv("aes-256-gcm",key,iv); const ciphertext=Buffer.concat([c.update(value,"utf8"),c.final()]); return {algorithm:"aes-256-gcm",iv:iv.toString("base64"),tag:c.getAuthTag().toString("base64"),ciphertext:ciphertext.toString("base64")}; }
export function decryptSecret(e:Envelope,key:Buffer){ const d=createDecipheriv("aes-256-gcm",key,Buffer.from(e.iv,"base64"));d.setAuthTag(Buffer.from(e.tag,"base64"));return Buffer.concat([d.update(Buffer.from(e.ciphertext,"base64")),d.final()]).toString("utf8"); }
export function redactCredential(c:{name:string}&Envelope){return {name:c.name,configured:Boolean(c.ciphertext)}}
